/*
 * area_$get_aste - get (activating if need be) the ASTE of one area segment
 *
 * Original address: 0x00E09A6A (module-local; the SAU2 map has no symbol
 * here, Ghidra carries the tree name)
 * Size: 708 bytes (0x00E09A6A .. 0x00E09D2D)
 * Generated by: Claude Opus 5.5
 *
 * Callers (all with ML lock 0x12 held and A5 = 0xE1E118, AREA_$GLOBALS):
 * area_$free_segments (0x00E0836E), AREA_$COPY (0x00E092B6, 0x00E092E2),
 * area_$find_entry_by_uid (0x00E094DC).
 *
 * The slot is the area_$seg_slot_t that covers a group of eight segments:
 * `bits' says which of the eight have been allocated, state bit 7 says
 * aste_index names the group's chain of active ASTEs (otherwise the cell's
 * low 22 bits are the disk address of the group's page-map block) and
 * state bit 6 marks it in transition.
 *
 * Frame (link.w A6,-0x24; D2-D7/A2-A4 saved): (0x08) area_id -> D6w,
 * (0x0A) slot -> D7, (0x0E) seg_idx -> D2w, (0x10) in_trans_held -> D4b,
 * (0x12) create -> D5b, (0x14) status; (-0x08) daddr, (-0x10) the ASTE's
 * segment-map row.  D3w = seg_idx & 7.  The result is A2, moved to A0.
 *
 * Blocks:
 *   0x00E09A8A  *status := 0
 *   0x00E09A90-0x00E09AA4  unless in_trans_held: A2 := slot + 1 and wait
 *                          (area_$wait_pite_in_trans) while state bit 6
 *   0x00E09AA6-0x00E09AF0  state bit 7: walk the chain from
 *                          AST_ASTE_ENTRY(aste_index) for segment seg_idx;
 *                          in transition -> AST_$WAIT_FOR_AST_INTRANS and
 *                          start over; found -> wire_count += 1,
 *                          ASTE_FLAG_LOCKED, return it AT ONCE (no release)
 *   0x00E09AF2-0x00E09B00  not found and !create: status 0x00030004, return
 *                          A2 without the release
 *   0x00E09B04-0x00E09B80  state bit 6 := 1; AST_$ALLOCATE_ASTE; its `aote'
 *                          is the AREA ENTRY; AST_$ASTE_AREA_CNT += 1;
 *                          segment, page_count 0, wire_count 1, flags
 *                          -IN_TRANS +LOCKED -DIRTY +AREA, REMOTE = (entry
 *                          remote_volx <> 0); A1 := its segment-map row
 *   0x00E09B84-0x00E09C92  segment allocated: local - ML_$UNLOCK(0x12),
 *                          DBUF_$GET_BLOCK of the group's page-map block,
 *                          relock, copy its 0x80 bytes for this segment,
 *                          DBUF_$SET_BUFF(8); remote - area_$rpmap_get and
 *                          copy the same 0x80 bytes from the cached page.
 *                          A failure frees the new ASTE (0x00E09C68) and
 *                          returns whatever A2 then holds
 *   0x00E09C94-0x00E09CAC  segment new: clear the row, set its bit, mark the
 *                          ASTE dirty
 *   0x00E09CB2-0x00E09D0A  chain the ASTE: onto the group's chain (sharing
 *                          its fm_block) or as its first member (fm_block :=
 *                          daddr << 4, state bit 7 := 1); fm_block's low
 *                          nibble := seg_idx & 7; slot.aste_index :=
 *                          aste->seg_index
 *   0x00E09D0C-0x00E09D1C  unless in_trans_held: state bit 6 := 0,
 *                          EC_$ADVANCE(&AREA_$PITE_IN_TRANS_EC)
 *
 * Quirk: when in_trans_held is TRUE and the not-found/!create exit is taken
 * the image returns its CALLER's A2 (never loaded here); the C returns NULL
 * there.  Every caller tests the status first.
 */

#include "area/area_internal.h"
#include "dbuf/dbuf.h"
#include "pmap/pmap.h"
#include "anon/anon.h"

/* `move.l #0x30004,(A0)` 0x00E09AFA (stcodes 30004) */
#define AREA_GA_NOT_ACTIVE_STATUS   status_$ast_segment_not_deactivatable
/* `move.l #0x10000,-(SP)` 0x00E09BDC: block_type 1, flags 0 */
#define AREA_GA_DBUF_BLOCK_TYPE     1
/* `move.w #0x8,-(SP)` 0x00E09C38 */
#define AREA_GA_DBUF_RELEASE        DBUF_RELEASE_CLEAN
/* `moveq #0x1f,D0` + dbf: one 0x80-byte segment map */
#define AREA_GA_ROW_LONGS           32

static void area_$copy_row(uint32_t *row, const uint8_t *page, uint16_t group)
{
    const uint32_t *src = (const uint32_t *)(page + (int16_t)(uint16_t)(group << 7));
    int k;

    for (k = 0; k < AREA_GA_ROW_LONGS; k++) {
        row[k] = src[k];
    }
}

struct aste_t *area_$get_aste(int16_t area_id, area_$seg_slot_t *slot,
                              int16_t seg_idx, int8_t in_trans_held,
                              int8_t create, status_$t *status_p)
{
    struct aste_t *result = NULL;   /* A2 */
    aste_t *aste;                   /* A0 / A3 */
    aste_t *other;
    area_$entry_t *entry;
    uint32_t *row;                  /* (-0x10,A6) */
    uint32_t daddr;                 /* (-0x8,A6) */
    void *page;
    uint16_t group;                 /* D3w */
    int k;

    /* 0x00E09A8A-0x00E09A8E */
    *status_p = status_$ok;
    group = (uint16_t)seg_idx & 7;

    /* 0x00E09A90-0x00E09AA4 */
    if (in_trans_held >= 0) {
        result = (struct aste_t *)&slot->state;
        while ((slot->state & AREA_SLOT_IN_TRANS) != 0) {
            area_$wait_pite_in_trans();
        }
    }

retry:
    /* 0x00E09AA6-0x00E09AF0 */
    if ((int8_t)slot->state < 0) {
        for (aste = AST_ASTE_ENTRY(slot->aste_index); aste != NULL;
             aste = aste->next) {
            if (aste->segment == (uint16_t)seg_idx) {
                if ((int16_t)aste->flags < 0) {
                    AST_$WAIT_FOR_AST_INTRANS();
                    goto retry;
                }
                aste->wire_count++;
                aste->flags |= ASTE_FLAG_LOCKED;
                return aste;
            }
        }
    }

    /* 0x00E09AF2-0x00E09B00 */
    if (create >= 0) {
        *status_p = AREA_GA_NOT_ACTIVE_STATUS;
        return result;
    }

    /* 0x00E09B04-0x00E09B1E */
    slot->state |= AREA_SLOT_IN_TRANS;
    entry = AREA_ID_TO_ENTRY((uint16_t)area_id);
    result = (struct aste_t *)entry;

    /* 0x00E09B22-0x00E09B6A */
    aste = AST_$ALLOCATE_ASTE();
    aste->aote = (struct aote_t *)entry;
    AST_$ASTE_AREA_CNT++;
    aste->segment = (uint16_t)seg_idx;
    aste->page_count = 0;
    aste->wire_count = 1;
    aste->flags &= ~ASTE_FLAG_IN_TRANS;
    aste->flags |= ASTE_FLAG_LOCKED;
    aste->flags &= ~ASTE_FLAG_DIRTY;
    aste->flags |= ASTE_FLAG_AREA;
    aste->flags = (uint16_t)((aste->flags & ~ASTE_FLAG_REMOTE) |
                             (entry->remote_volx != 0 ? ASTE_FLAG_REMOTE : 0));

    /* 0x00E09B6E-0x00E09B80 */
    row = (uint32_t *)&PMAP_SEGMAP_ROW(aste->seg_index)[0];

    /* 0x00E09B84-0x00E09B8C btst.l D3,D0 */
    if (((slot->bits >> group) & 1) != 0) {
        if (entry->remote_volx == 0) {
            /* 0x00E09B98-0x00E09BC4 */
            if ((int8_t)slot->state < 0) {
                daddr = AST_ASTE_ENTRY(slot->aste_index)->fm_block >> 4;
            } else {
                daddr = AREA_SLOT_LONG(slot) & AREA_SLOT_DADDR_MASK;
            }

            /* 0x00E09BC8-0x00E09C0C */
            ML_$UNLOCK(ML_LOCK_AST);
            page = DBUF_$GET_BLOCK((uint16_t)entry->volx, (int32_t)daddr,
                                   &ANON_$UID, daddr, AREA_GA_DBUF_BLOCK_TYPE,
                                   0, status_p);
            result = (struct aste_t *)page;
            ML_$LOCK(ML_LOCK_AST);

            if (*status_p != status_$ok) {
                goto fail;
            }
            /* 0x00E09C16-0x00E09C48 */
            area_$copy_row(row, (const uint8_t *)page, group);
            DBUF_$SET_BUFF(page, AREA_GA_DBUF_RELEASE, status_p);
        } else {
            /* 0x00E09C4A-0x00E09C66 */
            page = area_$rpmap_get(entry, (uint16_t)seg_idx, 0, 0, status_p);
            if (*status_p != status_$ok) {
                goto fail;
            }
            /* 0x00E09C76-0x00E09C92 */
            area_$copy_row(row, (const uint8_t *)page, group);
        }
    } else {
        /* 0x00E09C94-0x00E09CAC */
        for (k = 0; k < AREA_GA_ROW_LONGS; k++) {
            row[k] = 0;
        }
        slot->bits = (uint8_t)(slot->bits | (1u << group));
        aste->flags |= ASTE_FLAG_DIRTY;
    }

    /* 0x00E09CB2-0x00E09CF2 */
    if ((int8_t)slot->state < 0) {
        other = AST_ASTE_ENTRY(slot->aste_index);
        aste->next = other;
        aste->fm_block = other->fm_block;
    } else {
        aste->next = NULL;
        aste->fm_block = (aste->fm_block & 0xF) |
                         ((AREA_SLOT_LONG(slot) & AREA_SLOT_DADDR_MASK) << 4);
        slot->state |= AREA_SLOT_HAS_ASTE;
    }

    /* 0x00E09CF8-0x00E09D0A */
    aste->fm_block = (aste->fm_block & ~0xFu) | group;
    slot->aste_index = aste->seg_index;
    result = aste;
    goto release;

fail:
    /* 0x00E09C68-0x00E09C70 */
    AST_$FREE_ASTE(aste);

release:
    /* 0x00E09D0C-0x00E09D1C */
    if (in_trans_held >= 0) {
        slot->state &= (uint8_t)~AREA_SLOT_IN_TRANS;
        EC_$ADVANCE(&AREA_$PITE_IN_TRANS_EC);
    }
    return result;
}
